import{c as e,Q as o,j as r,m as a}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"CJK / 非英文語系 Token 消耗深度研究","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-06-cjk-token-tax-research.md","filePath":"research/reports/2026-06-06-cjk-token-tax-research.md","lastUpdated":1780842316000}'),d={name:"research/reports/2026-06-06-cjk-token-tax-research.md"};function n(s,t,l,i,h,g){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="cjk-非英文語系-token-消耗深度研究" tabindex="-1">CJK / 非英文語系 Token 消耗深度研究 <a class="header-anchor" href="#cjk-非英文語系-token-消耗深度研究" aria-label="Permalink to &quot;CJK / 非英文語系 Token 消耗深度研究&quot;">​</a></h1><blockquote><p>2026-06-06 · feature/cjk-token-research · 主題：LLM tokenizer 對 CJK 的 token 稅，及對 auto-load / 日常消耗的影響 方法：2 researcher 並行（學術 + 實務）+ 使用者參考文章 + tiktoken 親驗 + advisor 校準。 <strong>信度標註</strong>：[親驗] = tiktoken 本地實測｜[論文] = 同儕審查｜[三方] = 工程部落格實測｜[unverified] = 軼事/未獨立驗證。</p></blockquote><hr><h2 id="tl-dr-給-zeuik-的三個決策結論" tabindex="-1">TL;DR（給 Zeuik 的三個決策結論） <a class="header-anchor" href="#tl-dr-給-zeuik-的三個決策結論" aria-label="Permalink to &quot;TL;DR（給 Zeuik 的三個決策結論）&quot;">​</a></h2><ol><li><p><strong>CJK token 稅是真的，但「倍率」要看測什麼維度</strong>：字元效率差 5–6×（[親驗] 英文 5.9 vs 繁中 1.1 chars/token），但語意等量內容只差 1.3–2.4×（tokenizer 而定）。「15× 是 CJK」是誤傳——那是 Burmese/Amharic 等低資源語言。</p></li><li><p><strong>改英文 / 文言文化都不是省 token 的正解</strong>：英文 1:1 直譯 o200k 省 ~17% 但多 16.5% bytes，且 input 軸被 prompt cache 攤銷到邊際 ≈0（詳見 §4 + 附報告）。<strong>文言文對現行規則反而更貴</strong>（o200k 文言 293 vs 現行 251，+17%），且 Claude 古文理解 −20pp、指令幻覺↑（§7）。真正槓桿是<strong>結構下沉</strong>非語言切換。</p></li><li><p><strong>你的規則已在甜蜜點，且 Claude 真實倍率本機無法精確驗</strong>：量測證明現行 core.md 規則比刻意「精練」版還精練（§7）。Claude 中文 ~1.71× vs OpenAI ~1.15× 維持 [三方]（tokenizer 不公開 + 本機無 API key；<code>claude -p</code> 差分法被 cache 污染不可用，見 §4a-bis）。精確值需 cloud session <code>count_tokens</code>（§7.3）。</p></li></ol><hr><h2 id="§1-核心發現表-語言-×-tokenizer-×-倍率-×-信度" tabindex="-1">§1 核心發現表（語言 × tokenizer × 倍率 × 信度） <a class="header-anchor" href="#§1-核心發現表-語言-×-tokenizer-×-倍率-×-信度" aria-label="Permalink to &quot;§1 核心發現表（語言 × tokenizer × 倍率 × 信度）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>語言</th><th>Tokenizer</th><th>倍率（相對英文）</th><th>測量維度</th><th>信度</th></tr></thead><tbody><tr><td>繁中</td><td>o200k_base (GPT-4o)</td><td>1.29–2.33×</td><td>語意等量短句</td><td>[親驗]</td></tr><tr><td>繁中</td><td>cl100k_base (GPT-4)</td><td>2.43–4.50×</td><td>語意等量短句</td><td>[親驗]</td></tr><tr><td>繁中</td><td>o200k_base</td><td>5.4×</td><td>字元效率（chars/token 5.9→1.1）</td><td>[親驗]</td></tr><tr><td>簡中</td><td>cl100k_base</td><td>繁中的 ~0.5–0.9×</td><td>繁簡同義對比</td><td>[親驗]</td></tr><tr><td>中文</td><td>Claude (逆向)</td><td>1.71×</td><td>語意等量 vs Claude 英文基線</td><td>[三方] Komatsuzaki，作者自承無第三方驗證</td></tr><tr><td>中文</td><td>OpenAI</td><td>1.15×</td><td>語意等量（簡中長文）</td><td>[三方]</td></tr><tr><td>日文</td><td>cl100k_base</td><td>~2.12×</td><td>平均估算</td><td>[unverified]</td></tr><tr><td>韓文</td><td>cl100k / Claude</td><td>2–3×</td><td>短指令</td><td>[unverified] 社群實測</td></tr><tr><td>Burmese/Amharic</td><td>多 tokenizer</td><td>高達 10–15×</td><td>低資源語言</td><td>[論文] Petrov 2023</td></tr></tbody></table><p><strong>繁體 vs 簡體 [親驗]</strong>：cl100k 下繁體最高達簡體 2×（「解釋這個架構並修復錯誤」28 vs 「解释…」14 tokens）；o200k 縮小到 1.3–1.5×。<strong>你寫台灣繁中 = 比簡中用戶多付 token</strong>。</p><hr><h2 id="§2-三個常見誤解的澄清" tabindex="-1">§2 三個常見誤解的澄清 <a class="header-anchor" href="#§2-三個常見誤解的澄清" aria-label="Permalink to &quot;§2 三個常見誤解的澄清&quot;">​</a></h2><ol><li><p><strong>「15× 是 CJK」❌</strong> — Petrov et al. 2023 (NeurIPS) 測 FLORES-200 × 17 tokenizer，15× 指 Burmese/Amharic 等形態複雜低資源語言。CJK 落在 1.3–3× 區間。</p></li><li><p><strong>「字元效率差距 = 成本差距」❌</strong> — 中文 1 char/token vs 英文 4–6 是<strong>字元層</strong> 5–6× 差距；但中文字元語意密度高，相同意思的文章 token 差距縮到 1.15–2.4×。兩個數字都對，測不同維度。<strong>引用時必須標明測哪個</strong>。</p></li><li><p><strong>「tokenizer 是語言宿命」❌</strong> — 同樣中文：GLM 0.92× &lt; Qwen2 1.03× &lt; GPT/Llama cl100k 1.15× &lt; Claude 1.71×。差異來自訓練語料 CJK 配比，非語言本質。CJK 優化 tokenizer（Qwen/GLM/DeepSeek）可達英文平價甚至更省。</p></li></ol><hr><h2 id="§3-claude-vs-openai-矛盾的-reconcile-不裁決-是兩個維度" tabindex="-1">§3 Claude vs OpenAI 矛盾的 reconcile（不裁決，是兩個維度） <a class="header-anchor" href="#§3-claude-vs-openai-矛盾的-reconcile-不裁決-是兩個維度" aria-label="Permalink to &quot;§3 Claude vs OpenAI 矛盾的 reconcile（不裁決，是兩個維度）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>來源</th><th>宣稱</th><th>測量基礎</th></tr></thead><tbody><tr><td>使用者參考文章（Komatsuzaki）</td><td>Claude 中文 <strong>1.71×</strong> worse</td><td>語意等量內容，<strong>相對 Claude 自己的英文基線</strong></td></tr><tr><td>researcher 子 agent</td><td>Claude 對中文<strong>更省</strong>（机器学习 3 vs GPT 4 tokens）</td><td>單一簡中詞，<strong>絕對 token 數</strong></td></tr></tbody></table><p><strong>兩者皆可成立</strong>：Claude 可以「單個 CJK 詞 tokenize 得很緊」<strong>同時</strong>「相對它極高效的英文基線仍貴 1.71×」。因為 Claude 英文 tokenizer 特別高效，分母小 → 比值大。<strong>這不是誰對誰錯，是分母不同</strong>。</p><p>⚠️ <strong>本地驗證限制</strong>：Claude tokenizer 詞彙表不公開；<code>count_tokens</code> API 需 cloud session 的 ingress token（本機 session 無，見 <code>refs/claude-oauth-token.md</code>）。<code>claude -p</code> 差分法<strong>無法</strong>精確量跨語言差（被 cache 邊界污染 1.7×，見 §4a-bis 判別實驗）。故 Claude 中文 <strong>1.71× 維持 [三方] 信度</strong>，未升 [親驗]。<strong>唯一乾淨的本機 Claude 跨語言數字需 cloud session <code>count_tokens</code></strong>——建議在有 ingress token 的 cloud session 跑 <code>client.messages.count_tokens()</code> 切語意等量 TC/EN 對照。</p><hr><h2 id="§4-對你-workspace-的直接影響-最重要" tabindex="-1">§4 對你 workspace 的直接影響（最重要） <a class="header-anchor" href="#§4-對你-workspace-的直接影響-最重要" aria-label="Permalink to &quot;§4 對你 workspace 的直接影響（最重要）&quot;">​</a></h2><h3 id="_4a-auto-load-現況-親驗" tabindex="-1">4a. Auto-load 現況 [親驗] <a class="header-anchor" href="#_4a-auto-load-現況-親驗" aria-label="Permalink to &quot;4a. Auto-load 現況 [親驗]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>檔案</th><th style="text-align:right;">bytes</th><th style="text-align:right;">o200k tokens</th><th style="text-align:right;">B/token</th></tr></thead><tbody><tr><td>CLAUDE.md</td><td style="text-align:right;">2,348</td><td style="text-align:right;">804</td><td style="text-align:right;">2.92</td></tr><tr><td>core.md</td><td style="text-align:right;">9,584</td><td style="text-align:right;">3,126</td><td style="text-align:right;">3.07</td></tr><tr><td>context-management.md</td><td style="text-align:right;">2,099</td><td style="text-align:right;">655</td><td style="text-align:right;">3.20</td></tr><tr><td>output-discipline.md</td><td style="text-align:right;">1,472</td><td style="text-align:right;">459</td><td style="text-align:right;">3.21</td></tr><tr><td>subagent-strategy.md</td><td style="text-align:right;">3,223</td><td style="text-align:right;">994</td><td style="text-align:right;">3.24</td></tr><tr><td><strong>TOTAL</strong></td><td style="text-align:right;"><strong>18,726</strong></td><td style="text-align:right;"><strong>~6,038</strong></td><td style="text-align:right;"><strong>3.10</strong></td></tr></tbody></table><p>（o200k 為 GPT proxy。）</p><h3 id="_4a-bis-⚠️-差分法的限制-撤回先前錯誤結論-2026-06-06-修正" tabindex="-1">4a-bis. ⚠️ 差分法的限制（撤回先前錯誤結論，2026-06-06 修正） <a class="header-anchor" href="#_4a-bis-⚠️-差分法的限制-撤回先前錯誤結論-2026-06-06-修正" aria-label="Permalink to &quot;4a-bis. ⚠️ 差分法的限制（撤回先前錯誤結論，2026-06-06 修正）&quot;">​</a></h3><p><strong>先前版本宣稱用 <code>claude -p</code> 差分法量出「真實 Claude auto-load = 8,527 token，proxy 低估 41%」——此結論已撤回，是測量假象。</strong></p><p><strong>判別實驗推翻</strong>（advisor 攔下 + 親驗）：對一個 99.2% ASCII 的純英文檔（11,217 字元）跑差分法，得 4,475 token = <strong>2.5 chars/token</strong>。但英文真實密度 ~4 chars/token（o200k 同檔報 2,619 token = 4.28 chars/token）。<strong>英文不可能 2.5 chars/token</strong> → 差分法 <code>FULL − EMPTY</code> 被 <strong>cache block 邊界 / 最小快取粒度 / CLAUDE.md 注入位置</strong>系統性污染，高估約 <strong>1.7×</strong>。</p><table tabindex="0"><thead><tr><th>量法</th><th>效力</th><th>結論</th></tr></thead><tbody><tr><td><code>claude -p</code> MAGIC_TOKEN 行為測試</td><td>✅ 有效</td><td>確認 <code>claude -p</code> 真 cold-load local CLAUDE.md</td></tr><tr><td><code>claude -p</code> 差分 order-of-magnitude</td><td>✅ 有效</td><td>auto-load 約數千 token 級</td></tr><tr><td><code>claude -p</code> 差分<strong>跨語言精確比較</strong></td><td>❌ 污染 1.7×</td><td><strong>不可用</strong>——不能據此算 TC vs EN 精確差</td></tr><tr><td>Claude <code>count_tokens</code> API</td><td>⛔ 本機不可用</td><td>需 cloud session 的 ingress token（見 <code>refs/claude-oauth-token.md</code>）</td></tr></tbody></table><p><strong>誠實結論</strong>：本機<strong>無法</strong>精確量 Claude 真實 token。auto-load 成本維持 <strong>o200k proxy 6,038 token</strong> [親驗-proxy]，並標明「Claude 對繁中實際更貴（§3 1.71×），故真實值高於 6,038，但精確值需 cloud session <code>count_tokens</code> 才能定」。<strong>先前 commit 55261fc9 的 8,527 / 「省 20%→省 2.9%」推翻均作廢。</strong></p><h3 id="_4b-改英文的-a-b-實測-親驗-4-段代表性規則" tabindex="-1">4b. 改英文的 A/B 實測 [親驗]（4 段代表性規則） <a class="header-anchor" href="#_4b-改英文的-a-b-實測-親驗-4-段代表性規則" aria-label="Permalink to &quot;4b. 改英文的 A/B 實測 [親驗]（4 段代表性規則）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指標</th><th style="text-align:right;">繁中</th><th style="text-align:right;">英文</th><th style="text-align:right;">變化</th></tr></thead><tbody><tr><td>o200k tokens</td><td style="text-align:right;">237</td><td style="text-align:right;">188</td><td style="text-align:right;"><strong>−20.7%</strong></td></tr><tr><td>cl100k tokens</td><td style="text-align:right;">341</td><td style="text-align:right;">190</td><td style="text-align:right;"><strong>−44.3%</strong></td></tr><tr><td>utf-8 bytes</td><td style="text-align:right;">746</td><td style="text-align:right;">989</td><td style="text-align:right;"><strong>+32.6%</strong></td></tr><tr><td>token/byte</td><td style="text-align:right;">0.318</td><td style="text-align:right;">0.190</td><td style="text-align:right;">英文每 byte 更省</td></tr></tbody></table><h3 id="_4c-結論-你的「byte-cap」單位選錯了" tabindex="-1">4c. 結論：你的「byte cap」單位選錯了 <a class="header-anchor" href="#_4c-結論-你的「byte-cap」單位選錯了" aria-label="Permalink to &quot;4c. 結論：你的「byte cap」單位選錯了&quot;">​</a></h3><ul><li><strong>改英文確實省 token</strong>（−20% 到 −44%，看 tokenizer），prompt cache 沒命中時直接省 input 成本。</li><li><strong>但會撞破 19,000 byte cap</strong>：英文多 32.6% bytes → 同樣規則改英文，byte 爆但 token 反降。</li><li><strong>根因</strong>：byte cap 是「繁中 ≈ 3 B/token」時代的 token proxy。當內容語言改變，byte 與 token 解耦——<strong>byte 守得住不代表 token 守得住，反之亦然</strong>。</li><li><strong>你 CLAUDE.md 已寫對方向</strong>：output-discipline.md「內部 instructions 可用英文，回應維持繁中」。本研究 [親驗] 量化了該規則的真實收益：auto-load 全英文化理論上省 ~20% Claude input token（cache miss 時）。</li></ul><hr><h2 id="§5-回答使用者-四檔改英文-對效率-token-有幫助嗎" tabindex="-1">§5 回答使用者：四檔改英文，對效率/token 有幫助嗎？ <a class="header-anchor" href="#§5-回答使用者-四檔改英文-對效率-token-有幫助嗎" aria-label="Permalink to &quot;§5 回答使用者：四檔改英文，對效率/token 有幫助嗎？&quot;">​</a></h2><p><strong>收益被高估了——重新評估後：不值得做。</strong></p><table tabindex="0"><thead><tr><th>維度</th><th>影響</th><th>量化</th></tr></thead><tbody><tr><td>Token 消耗</td><td>小降</td><td>o200k 省 ~17%（[親驗]，1:1 直譯 6,038→4,997）；但 Claude 真值未定</td></tr><tr><td>Byte cap</td><td>爆</td><td>+16.5% bytes（18,726→21,824）→ 撞 19,000 byte cap</td></tr><tr><td><strong>Cache 命中時</strong></td><td><strong>收益≈0</strong></td><td>靜態前綴命中 cache 後 input 降 78–90%，語言省的 token 被攤銷掉——這是關鍵：日常 session 大多 cache 命中</td></tr><tr><td>合規風險</td><td>低</td><td>規則是給 Claude 讀的指令（非回應），改英文不違反繁中鐵律</td></tr></tbody></table><p><strong>修正結論</strong>：<s>值得做</s> → <strong>不值得</strong>。input 軸被 cache 攤銷、又多 16.5% bytes，工程/合規成本不划算。守繁中鐵律更安全。<strong>真正該省的走結構槓桿</strong>（低頻規則下沉 refs/，見附報告 <code>2026-06-06-autoload-token-optimization.md</code>），非語言切換。</p><hr><h2 id="§7-文言文-精練繁中評估-input-output-雙軸" tabindex="-1">§7 文言文 / 精練繁中評估（input + output 雙軸） <a class="header-anchor" href="#§7-文言文-精練繁中評估-input-output-雙軸" aria-label="Permalink to &quot;§7 文言文 / 精練繁中評估（input + output 雙軸）&quot;">​</a></h2><blockquote><p>完整版見 <code>2026-06-06-classical-chinese-token-eval.md</code>；此處摘核心。</p></blockquote><h3 id="_7-1-四階文本-o200k-量測-親驗" tabindex="-1">7.1 四階文本 o200k 量測 [親驗] <a class="header-anchor" href="#_7-1-四階文本-o200k-量測-親驗" aria-label="Permalink to &quot;7.1 四階文本 o200k 量測 [親驗]&quot;">​</a></h3><p>同 5 條規則（含生產紅線）：</p><table tabindex="0"><thead><tr><th>版本</th><th style="text-align:right;">o200k token</th><th style="text-align:right;">vs 現行</th></tr></thead><tbody><tr><td><strong>現行 core.md（真實 baseline）</strong></td><td style="text-align:right;"><strong>251</strong></td><td style="text-align:right;">—</td></tr><tr><td>人造「精練」</td><td style="text-align:right;">302</td><td style="text-align:right;">+20%</td></tr><tr><td>人造「現代囉嗦」</td><td style="text-align:right;">402</td><td style="text-align:right;">+60%</td></tr><tr><td>文言文</td><td style="text-align:right;">293</td><td style="text-align:right;"><strong>+17%（更貴）</strong></td></tr></tbody></table><p><strong>反直覺結論</strong>：① <strong>你現行規則已是最精練</strong>（251 打敗所有人造版）；② <strong>文言文反而比現況貴 17%</strong>——字數少≠token 少，文言罕字（之乎者也）在 BPE 反 fragment。先前用「囉嗦版」當 baseline 得「精練省 25%」是稻草人，已修正（advisor 攔下）。</p><h3 id="_7-2-文言文兩個硬傷-論文" tabindex="-1">7.2 文言文兩個硬傷 [論文] <a class="header-anchor" href="#_7-2-文言文兩個硬傷-論文" aria-label="Permalink to &quot;7.2 文言文兩個硬傷 [論文]&quot;">​</a></h3><ul><li><strong>省幅有限</strong>：文言只省白話 21%（Claude 實測 38→30 tok），換英文省 50%、砍 output 更多。</li><li><strong>理解力雙降</strong>：WYWEB 模型 75.9 vs 人類 88；Fùxì GPT-4o 生成僅 35.7%（差 42.5pp）；WenyanGPT NER 91% vs GPT-4o 68%（−23pp）。指令文言文化 → 幻覺率↑。</li></ul><h3 id="_7-3-output-軸-更大槓桿-精確量測指引" tabindex="-1">7.3 output 軸（更大槓桿）+ 精確量測指引 <a class="header-anchor" href="#_7-3-output-軸-更大槓桿-精確量測指引" aria-label="Permalink to &quot;7.3 output 軸（更大槓桿）+ 精確量測指引&quot;">​</a></h3><ul><li><strong>output 省 token：簡答 &gt; 文言文回應</strong>。叫 Claude「不要前言、工具後只報結果」直接砍結構；你的 <code>output-discipline.md</code>（≤150字）<strong>已實作此最高 ROI 手段</strong>。文言文回應反增你的可讀性負擔。</li><li><strong>input 軸被 cache 攤銷邊際≈0</strong>（§4 break-even=第2請求）。兩軸文言文化皆不划算。</li><li><strong>精確 Claude 量測</strong>（取代污染的差分法）：<code>scripts/count-tokens-claude.py</code> + 四階樣本（<code>2026-06-06-classical-chinese-samples/</code>）。途徑：Console <code>sk-ant-api-*</code> key（<strong>非</strong> <code>setup-token</code> 的 OAuth token——後者被 ToS 限定不能打 raw API）或 cloud session ingress token。count_tokens 免費。<strong>會驗證 o200k 答不了的：文言罕字在 Claude 是否 fragment。</strong></li></ul><hr><h2 id="§6-來源清單" tabindex="-1">§6 來源清單 <a class="header-anchor" href="#§6-來源清單" aria-label="Permalink to &quot;§6 來源清單&quot;">​</a></h2><p><strong>論文（同儕審查）</strong></p><ul><li>Petrov et al. 2023, <em>Language Model Tokenizers Introduce Unfairness Between Languages</em>, NeurIPS — <a href="https://arxiv.org/abs/2305.15425" target="_blank" rel="noreferrer">https://arxiv.org/abs/2305.15425</a></li><li>Rust et al. 2021, <em>How Good is Your Tokenizer?</em>, ACL — <a href="https://aclanthology.org/2021.acl-long.243.pdf" target="_blank" rel="noreferrer">https://aclanthology.org/2021.acl-long.243.pdf</a></li><li><em>The Token Tax: Systematic Bias in Multilingual Tokenization</em> — <a href="https://arxiv.org/html/2509.05486v1" target="_blank" rel="noreferrer">https://arxiv.org/html/2509.05486v1</a></li></ul><p><strong>三方實測</strong></p><ul><li>使用者參考：ai-coding.wiselychen.com — <em>非英語 Token 稅</em> — <a href="https://ai-coding.wiselychen.com/non-english-tax-tokenizer-cost-claude-openai/" target="_blank" rel="noreferrer">https://ai-coding.wiselychen.com/non-english-tax-tokenizer-cost-claude-openai/</a></li><li>Dylan Castillo — 多語言 chars/token (o200k) — <a href="https://dylancastillo.co/til/counting-tokens.html" target="_blank" rel="noreferrer">https://dylancastillo.co/til/counting-tokens.html</a></li><li>claudecodecamp.com — Claude 4.7 tokenizer 實測 — <a href="https://www.claudecodecamp.com/p/i-measured-claude-4-7-s-new-tokenizer-here-s-what-it-costs-you" target="_blank" rel="noreferrer">https://www.claudecodecamp.com/p/i-measured-claude-4-7-s-new-tokenizer-here-s-what-it-costs-you</a></li><li>Sander Land — Claude 3 tokenizer 逆向 — <a href="https://tokencontributions.substack.com/p/the-mystery-of-the-claude-3-tokenizer" target="_blank" rel="noreferrer">https://tokencontributions.substack.com/p/the-mystery-of-the-claude-3-tokenizer</a></li><li>tonybaloney.github.io — CJK in LLM pipelines</li></ul><p><strong>社群（信度低）</strong></p><ul><li>GitHub anthropics/claude-code #26401 — CJK 結構劣勢（Closed not planned）</li><li>OpenAI Community — Korean tokenizer efficiency</li></ul><p><strong>親驗腳本</strong>：本報告 §1/§4 tiktoken 數字可由 <code>python3 + tiktoken</code> 重現（cl100k_base / o200k_base）。</p>',56)])])}const k=e(d,[["render",n]]);export{u as __pageData,k as default};
